// ── Composables ───────────────────────────────────────────────────────────────

// ── Native view component registry ───────────────────────────────────────────
// Register platform-native Composables by name at app startup. The name is the
// Elixir module with "Elixir." stripped and "." replaced with "_":
//   MyApp.ChartComponent → "MyApp_ChartComponent"
//
//   MobNativeViewRegistry.register("MyApp_ChartComponent") { props, send ->
//       ChartView(data = props["data"]) { index ->
//           send("tapped", mapOf("index" to index))
//       }
//   }

typealias MobNativeSend = (event: String, payload: Map<String, Any>) -> Unit
typealias MobNativeViewFactory = @Composable (props: Map<String, Any?>, send: MobNativeSend) -> Unit

object MobNativeViewRegistry {
    private val factories = mutableMapOf<String, MobNativeViewFactory>()

    fun register(name: String, factory: MobNativeViewFactory) {
        factories[name] = factory
    }

    @Composable
    fun render(node: MobNode) {
        val name = node.props["module"] as? String ?: return
        val factory = factories[name] ?: return
        val handle = (node.props["component_handle"] as? Number)?.toInt() ?: return
        val send: MobNativeSend = { event, payload ->
            try {
                val json = org.json.JSONObject(payload).toString()
                nativeDeliverComponentEvent(handle, event, json)
            } catch (_: Exception) {}
        }
        factory(node.props, send)
    }

    external fun nativeDeliverComponentEvent(handle: Int, event: String, payloadJson: String)
}

/** Renders a MobNode tree produced by Mob.Renderer. */
@Composable
fun RenderNode(node: MobNode, modifier: Modifier = Modifier) {
    // KATI-BEGIN(K-29 max-font-scale) mob_new=0.4.20
    // max_font_scale — a ceiling on how far a subtree's TEXT may grow.
    //
    // Text sizes cross the wire in sp, so every label scales with the system
    // font size. That is right for body copy and wrong for a display title,
    // which starts large: screen 02's "Schedule" is 28sp, and at Android's 235%
    // Dynamic Type it wants ~290dp of the 272dp its column has, so it wrapped
    // mid-word — one word over three lines (#79).
    //
    // Capping the scale rather than the size keeps this an accessibility
    // decision instead of a hard-coded number: the title still grows, just no
    // further than the cap, while everything around it goes on to the full
    // 235%. Compose 1.8's autoSize would be the other answer; the BOM here is
    // 2024.02.00 (Compose 1.6) and does not have it.
    //
    // Applied by overriding LocalDensity for the subtree, which is what sp
    // resolution reads, so it needs no cooperation from any node type and
    // reaches children that were never told about it. density is passed
    // through untouched: dp must not move, or a capped title would also shrink
    // its own padding and corner radii.
    val cap = floatProp(node.props, "max_font_scale")
    val density = LocalDensity.current
    if (cap != null && cap > 0f && density.fontScale > cap) {
        CompositionLocalProvider(LocalDensity provides Density(density.density, cap)) {
            RenderNodeOffset(node, modifier)
        }
    } else {
        RenderNodeOffset(node, modifier)
    }
}

@Composable
private fun RenderNodeOffset(node: MobNode, modifier: Modifier) {
    // KATI-END(K-29 max-font-scale)
    val ox = floatProp(node.props, "offset_x") ?: 0f
    val oy = floatProp(node.props, "offset_y") ?: 0f
    if (ox != 0f || oy != 0f) {
        Box(modifier = Modifier.offset(x = ox.dp, y = oy.dp)) {
            RenderNodeInner(node, modifier)
        }
    } else {
        RenderNodeInner(node, modifier)
    }
}

@Composable
private fun RenderNodeInner(node: MobNode, modifier: Modifier) {
    // Apply on_tap as a clickable modifier for any node type except button —
    // button installs its own onClick via the Button composable. Mirrors iOS,
    // where most node types pick up onTapGesture via .ifLet(node.onTap).
    val tapHandle = intProp(node.props, "on_tap")
    // KATI-BEGIN(K-18 anchored-node) mob_new=0.4.20
    // `anchored` must be excluded here as well as `button`.
    //
    // WHY: on an anchored node `on_tap` is not "tap me" — it is the DISMISS
    // handler, the report of a tap that landed OUTSIDE the panel's window.
    // Kati.Components.Anchored deliberately ships `on_dismiss` down the wire as
    // `on_tap` because that is the only tap-shaped prop Mob.Renderer registers,
    // and MobAnchored reads it itself. Left in the generic branch, a clickable
    // would wrap the whole node and swallow taps meant for the trigger inside
    // it — the popover would open and then be impossible to operate.
    // was: if (tapHandle != null && node.type != "button")
    val tapModifier = if (tapHandle != null && node.type != "button" && node.type != "anchored") {
        modifier.clickable { MobBridge.nativeSendTap(tapHandle) }
    } else modifier
    // KATI-END(K-18 anchored-node)
    val m = tapModifier.then(nodeModifier(node.props))
    when (node.type) {
        "column" -> Column(modifier = m) {
            node.children.forEach { child ->
                val w = floatProp(child.props, "weight")
                // KATI-BEGIN(K-15 zero-weight) mob_new=0.4.20
                RenderNode(child, when {
                    w == null  -> Modifier
                    w > 0f     -> Modifier.weight(w)
                    else       -> Modifier.height(0.dp)
                })
                // KATI-END(K-15 zero-weight)
            }
        }
        "row" -> Row(modifier = m, verticalAlignment = rowAlignProp(node.props)) {
            node.children.forEach { child ->
                val w = floatProp(child.props, "weight")
                // KATI-BEGIN(K-15 zero-weight) mob_new=0.4.20
                // `Modifier.weight(0f)` THROWS — "invalid weight 0.0; must be
                // greater than zero" — and it is an uncaught IllegalArgument
                // on the main thread, so it kills the activity outright.
                //
                // Every progress bar in this app is drawn as two weighted
                // cells, `weight={fraction}` beside `weight={1.0 - fraction}`,
                // and 0% and 100% are ORDINARY DATA: a season with every
                // episode watched, a book not yet started. Ten screens compute
                // a weight this way, so this was a crash waiting behind normal
                // use — screen 04 hit it the moment the season pills became
                // real and S1 came back fully watched.
                //
                // Zero share of the remaining space means zero size along the
                // axis, which is exactly what the caller meant. Clamping to a
                // small positive weight instead would leave a visible sliver
                // of ink at 0%.
                RenderNode(child, when {
                    w == null  -> Modifier
                    w > 0f     -> Modifier.weight(w)
                    else       -> Modifier.width(0.dp)
                })
                // KATI-END(K-15 zero-weight)
            }
        }
        // Box defaults to fillMaxWidth (matching iOS .frame(maxWidth: .infinity))
        // when no explicit width is set; otherwise it uses the explicit
        // width applied via nodeModifier above.
        // contentAlignment derives from the "align" prop ("center" /
        // "top_leading" / etc.) — defaults to TopStart for back-compat.
        "box" -> {
            val hasWidth = floatProp(node.props, "width") != null
            // KATI-BEGIN(K-17 box-hugs-when-told) mob_new=0.4.20
            // `fill_width={false}` did NOTHING to a box. The branch consulted
            // only `width`, so a box with no numeric width was force-filled
            // whatever it asked for — `fill_width` was read in nodeModifier and
            // only ever tested for `== true`.
            //
            // That is upstream Mob's behaviour, not a Kati edit (the same lines
            // are in native/baseline/0.4.20), and it makes 18 of the vendored
            // Mishka Chelekom components unusable: chip, pill, mark and so
            // highlight, segmented-control segments, toggle, spoiler and
            // overflow-list's +N pill all define their entire silhouette by
            // hugging their content, and every one of them would draw as a
            // full-width bar. MishkaChip's own comment says `fill_width={false}`
            // fixes this on Android; against this bridge version it does not.
            //
            // A declared `width` still wins, so nothing that already sizes
            // itself changes. Only a box that explicitly asks to hug now hugs.
            val hugs = boolProp(node.props, "fill_width") == false
            val boxModifier = if (hasWidth || hugs) m else m.fillMaxWidth()
            // KATI-END(K-17 box-hugs-when-told)
            Box(modifier = boxModifier, contentAlignment = boxAlignProp(node.props)) {
                node.children.forEach { RenderNode(it) }
            }
        }
        "scroll" -> {
            val scrollState = rememberScrollState()
            if (node.props["axis"] == "horizontal") {
                Row(modifier = m.horizontalScroll(scrollState)) {
                    node.children.forEach { RenderNode(it) }
                }
            } else {
                Column(modifier = m.verticalScroll(scrollState).imePadding()) {
                    node.children.forEach { RenderNode(it) }
                }
            }
        }
        "text"       -> MobText(node, m)
        "button"     -> MobButton(node, m)
        "tab_bar"    -> MobTabBar(node, m)
        "text_field" -> MobTextField(node, m)
        "toggle"     -> MobToggle(node, m)
        "slider"     -> MobSlider(node, m)
        "divider"    -> MobDivider(node, m)
        "spacer"     -> MobSpacer(node, m)
        "progress"   -> MobProgress(node, m)
        "image"      -> MobImage(node, m)
        "icon"       -> MobIcon(node, m)
        "lazy_list"  -> MobLazyList(node, m)
        "video"          -> MobVideoPlayer(node, m)
        "web_view"       -> MobWebView(node, m)
        "native_view"    -> MobNativeViewRegistry.render(node)
        "canvas"         -> MobCanvas(node, m)
        "gpu_view"       -> MobGpuView(node, m)
        // KATI-BEGIN(K-18 anchored-node) mob_new=0.4.20
        // WHY: `when` here has no else arm, so an unhandled node type renders
        // as NOTHING — silently, with no log and no crash. Three vendored
        // components (MishkaPopover, MishkaTooltip, MishkaPreviewCard) build
        // `%{type: :anchored}` nodes and every one of them drew a blank until
        // this arm existed.
        "anchored"       -> MobAnchored(node, m)
        // KATI-END(K-18 anchored-node)
    }
}

// KATI-BEGIN(K-18 anchored-node) mob_new=0.4.20
// ── anchored ─────────────────────────────────────────────────────────────────
//
// WHY this exists: Kati.Components.MishkaPopover, MishkaTooltip and
// MishkaPreviewCard build `%{type: :anchored, ...}` nodes, and this bridge had
// no arm for them, so all three rendered as nothing at all.
//
// Exactly two children: [0] the ANCHOR (a popover's trigger), [1] the PANEL.
// The anchor renders in flow; the panel renders in its OWN window via
// androidx.compose.ui.window.Popup, so it OVERLAYS the page instead of taking a
// place in it. That is what the web does — its three headless engines set
// `position: fixed` and write viewport-space left/top — and it is the only
// arrangement no ancestor can defeat: a Box with corner_radius clips
// (nodeModifier, `m.clip(shape)`) and a vertical Scroll clips its main axis. An
// in-flow overlay inside either measures (0,0,0,0): invisible AND untappable,
// which is worse than the accordion it was meant to replace.
//
// Props (all read off THIS node, never off a child):
//
//   side              "top" | "right" | "bottom" | "left"    default "bottom"
//   align             "start" | "center" | "end"             default "center"
//   side_offset       dp gap between anchor and panel        default 0
//   align_offset      dp nudge along the align axis          default 0
//   panel_offset_x/y  dp raw nudge, applied last             default 0
//   flip              turn to the opposite side when the
//                     requested one has no room              default true
//   clamp             keep the panel inside the window       default true
//   edge_padding      dp kept clear of the window edges      default 8
//   panel_max_width   dp cap on the panel                    default screen - 2*edge
//   panel_max_height  dp cap on the panel                    default screen - 2*edge
//   focusable         let the panel take keyboard focus      default false
//
// NOT read: offset_x / offset_y. RenderNode wraps any node carrying those in a
// Box(Modifier.offset), which would move the ANCHOR, not the panel — hence the
// separate panel_offset_* names. Do not add them.
@Composable
private fun MobAnchored(node: MobNode, modifier: Modifier) {
    val anchor = node.children.getOrNull(0)
    val panel = node.children.getOrNull(1)

    // Closed (trigger alone) and pinned-open-with-no-trigger both degrade to a
    // plain Box, so the node keeps its place in the layout either way.
    if (panel == null) {
        Box(modifier = modifier) { anchor?.let { RenderNode(it) } }
        return
    }
    if (anchor == null) {
        Box(modifier = modifier) { RenderNode(panel) }
        return
    }

    val density = LocalDensity.current
    val cfg = LocalConfiguration.current
    // The window spans the display under edge-to-edge, so a bare 8dp pad would
    // let a panel land under the status bar. safeDrawing is added per edge; it
    // is zero on the axes that have no bar.
    val insets = WindowInsets.safeDrawing
    val ld = LocalLayoutDirection.current
    val edgeDp = floatProp(node.props, "edge_padding") ?: 8f
    val edgePx = with(density) { edgeDp.dp.roundToPx() }
    val displaySizePx = rememberRealDisplaySizePx()

    val provider =
        remember(node.props, density, insets, ld, cfg, displaySizePx) {
            MobAnchoredPositionProvider(
                side = node.props["side"] as? String ?: "bottom",
                align = node.props["align"] as? String ?: "center",
                sideOffset =
                    with(density) { (floatProp(node.props, "side_offset") ?: 0f).dp.roundToPx() },
                alignOffset =
                    with(density) { (floatProp(node.props, "align_offset") ?: 0f).dp.roundToPx() },
                nudgeX =
                    with(density) { (floatProp(node.props, "panel_offset_x") ?: 0f).dp.roundToPx() },
                nudgeY =
                    with(density) { (floatProp(node.props, "panel_offset_y") ?: 0f).dp.roundToPx() },
                padLeft = edgePx + insets.getLeft(density, ld),
                padTop = edgePx + insets.getTop(density),
                padRight = edgePx + insets.getRight(density, ld),
                padBottom = edgePx + insets.getBottom(density),
                flip = boolProp(node.props, "flip") ?: true,
                clamp = boolProp(node.props, "clamp") ?: true,
                // The DISPLAY, not windowSize. windowSize comes from
                // getWindowVisibleDisplayFrame, which under edge-to-edge is
                // smaller than what is actually drawn — a trigger sitting over
                // the gesture bar counted as off-screen and its panel stopped
                // being clamped, landing at x=-65dp.
                //
                // Configuration was the first attempt at "the display" and is
                // still short of it below API 35, where screenHeightDp excludes
                // the status and navigation bars — 851dp of a 923dp screen on a
                // Pixel 6. A trigger at 858dp then reads as off-screen and the
                // same -65dp escape comes back, on that API and no other, which
                // is why it survived: an API 36 emulator clamps correctly and an
                // API 34 one does not. getRealMetrics is the actual panel size
                // on every API this app supports (minSdk 28).
                screenWidth = displaySizePx.width,
                screenHeight = displaySizePx.height,
            )
        }

    // A Popup measures its content against the whole window, so a panel that
    // sets fill_width (MishkaPopover.panel/2 does by default) would be screen
    // wide and a long paragraph would never wrap short. Cap it here rather than
    // making every component carry a width.
    val maxW = (floatProp(node.props, "panel_max_width") ?: (cfg.screenWidthDp - 2f * edgeDp)).dp
    val maxH = (floatProp(node.props, "panel_max_height") ?: (cfg.screenHeightDp - 2f * edgeDp)).dp

    Box(modifier = modifier) {
        RenderNode(anchor)
        // `on_tap` on an anchored node means DISMISS, not "tap the anchor" —
        // RenderNodeInner skips its usual clickable branch for this type. The
        // BEAM still owns open/closed: the window does not close itself, it
        // reports the outside tap and the screen flips the assign, so the
        // trigger's open state can never disagree with the panel that is drawn.
        // Without a handler an outside tap does nothing.
        val dismiss = intProp(node.props, "on_tap")

        Popup(
            popupPositionProvider = provider,
            onDismissRequest = dismiss?.let { { MobBridge.nativeSendTap(it) } },
            properties =
                PopupProperties(
                    // focusable is what lets the window see a tap that lands
                    // outside it at all; without it dismissOnClickOutside can
                    // never fire.
                    focusable = boolProp(node.props, "focusable") ?: (dismiss != null),
                    dismissOnBackPress = false,
                    dismissOnClickOutside = dismiss != null,
                    // FALSE, deliberately. With clipping on, the window manager
                    // pins the popup inside the display whatever position it is
                    // given — so a panel whose anchor had scrolled far above the
                    // viewport (measured: anchor at y=-3658dp) was dragged back
                    // to y=94dp and sat there, following the user down the page.
                    // The position provider does the clamping instead, and only
                    // while the anchor is actually on screen.
                    clippingEnabled = false,
                ),
        ) {
            Box(modifier = Modifier.widthIn(max = maxW).heightIn(max = maxH)) { RenderNode(panel) }
        }
    }
}

/**
 * The physical panel size in pixels, system bars included.
 *
 * Neither of the obvious answers is this. `Configuration.screenWidthDp/HeightDp` drops
 * the status and navigation bars below API 35 but keeps them from 35 on, so the same
 * code reads two different screens depending on the device's API level. And
 * `getWindowVisibleDisplayFrame` is the visible frame, which under edge-to-edge is
 * smaller than what is actually drawn. Anchored positioning needs the real surface: a
 * trigger drawn over the gesture bar is on screen, and its panel has to be clamped.
 */
@Composable
private fun rememberRealDisplaySizePx(): IntSize {
    val context = LocalContext.current
    return remember(context) {
        val metrics = android.util.DisplayMetrics()
        @Suppress("DEPRECATION")
        (context.getSystemService(android.content.Context.WINDOW_SERVICE) as android.view.WindowManager)
            .defaultDisplay
            .getRealMetrics(metrics)
        IntSize(metrics.widthPixels, metrics.heightPixels)
    }
}

// The web's positionPopup(), transliterated. All three headless engines carry a
// byte-identical copy: a main-axis-only flip when BOTH halves hold, then an
// unconditional clamp on both axes. `align` is never flipped, and there is no
// shift-along-align fallback.
//
// anchorBounds arrives as parentLayoutCoordinates.positionInWindow() + size;
// windowSize is getWindowVisibleDisplayFrame. The returned IntOffset becomes
// params.x/params.y with gravity = START|TOP.
private class MobAnchoredPositionProvider(
    private val side: String,
    private val align: String,
    private val sideOffset: Int,
    private val alignOffset: Int,
    private val nudgeX: Int,
    private val nudgeY: Int,
    private val padLeft: Int,
    private val padTop: Int,
    private val padRight: Int,
    private val padBottom: Int,
    private val flip: Boolean,
    private val clamp: Boolean,
    private val screenWidth: Int,
    private val screenHeight: Int,
) : PopupPositionProvider {
    override fun calculatePosition(
        anchorBounds: IntRect,
        windowSize: IntSize,
        layoutDirection: LayoutDirection,
        popupContentSize: IntSize,
    ): IntOffset {
        val vw = windowSize.width
        val vh = windowSize.height
        val pw = popupContentSize.width
        val ph = popupContentSize.height
        val rtl = layoutDirection == LayoutDirection.Rtl

        // Mirror once, up front, the way the web does with isRTL; everything
        // after this is absolute arithmetic. (Kati runs RTL for real — see
        // K-12 rtl-root — so this branch is not theoretical here.)
        var s =
            if (!rtl) {
                side
            } else {
                when (side) {
                    "left" -> "right"
                    "right" -> "left"
                    else -> side
                }
            }
        val vertical = s == "top" || s == "bottom"
        val al =
            if (!rtl || !vertical) {
                align
            } else {
                when (align) {
                    "start" -> "end"
                    "end" -> "start"
                    else -> align
                }
            }
        val alOff = if (rtl && vertical) -alignOffset else alignOffset

        if (flip) {
            s =
                when (s) {
                    "bottom" ->
                        if (anchorBounds.bottom + sideOffset + ph > vh - padBottom &&
                            anchorBounds.top - sideOffset - ph > padTop
                        ) {
                            "top"
                        } else {
                            s
                        }
                    "top" ->
                        if (anchorBounds.top - sideOffset - ph < padTop &&
                            anchorBounds.bottom + sideOffset + ph < vh - padBottom
                        ) {
                            "bottom"
                        } else {
                            s
                        }
                    "right" ->
                        if (anchorBounds.right + sideOffset + pw > vw - padRight &&
                            anchorBounds.left - sideOffset - pw > padLeft
                        ) {
                            "left"
                        } else {
                            s
                        }
                    "left" ->
                        if (anchorBounds.left - sideOffset - pw < padLeft &&
                            anchorBounds.right + sideOffset + pw < vw - padRight
                        ) {
                            "right"
                        } else {
                            s
                        }
                    else -> s
                }
        }

        var x: Int
        var y: Int
        if (s == "top" || s == "bottom") {
            y =
                if (s == "bottom") {
                    anchorBounds.bottom + sideOffset
                } else {
                    anchorBounds.top - ph - sideOffset
                }
            // Note the sign asymmetry on "end": a positive align_offset pushes
            // the panel INWARD, exactly as the web engines do.
            x =
                when (al) {
                    "start" -> anchorBounds.left + alOff
                    "end" -> anchorBounds.right - pw - alOff
                    else -> anchorBounds.left + (anchorBounds.width - pw) / 2 + alOff
                }
        } else {
            x =
                if (s == "right") {
                    anchorBounds.right + sideOffset
                } else {
                    anchorBounds.left - pw - sideOffset
                }
            y =
                when (al) {
                    "start" -> anchorBounds.top + alOff
                    "end" -> anchorBounds.bottom - ph - alOff
                    else -> anchorBounds.top + (anchorBounds.height - ph) / 2 + alOff
                }
        }

        x += nudgeX
        y += nudgeY

        // Clamp only while the ANCHOR is on screen. Clamping unconditionally is
        // what made an open panel park itself at the top of the window and
        // follow the user down the page after its trigger had scrolled away —
        // measured: trigger at y=-3658dp, panel pinned at y=94dp and visible.
        // Off-screen anchor, off-screen panel; clippingEnabled then hides it,
        // which is what the web does when its reference scrolls out of view.
        val anchorOnScreen =
            anchorBounds.bottom > 0 && anchorBounds.top < screenHeight &&
                anchorBounds.right > 0 && anchorBounds.left < screenWidth

        if (clamp && anchorOnScreen) {
            // If the panel is wider than the room, the upper bound collapses to
            // the lower one and it pins flush at the leading edge — the edge
            // carrying the title. Same as the web's Math.min(Math.max(...)).
            x = x.coerceIn(padLeft, maxOf(padLeft, vw - pw - padRight))
            y = y.coerceIn(padTop, maxOf(padTop, vh - ph - padBottom))
        }
        return IntOffset(x, y)
    }
}
// KATI-END(K-18 anchored-node)

@Composable
private fun MobText(node: MobNode, modifier: Modifier) {
    val text          = node.props["text"] as? String ?: ""
    val color         = colorProp(node.props, "text_color")
    val fontSize      = sizeProp(node.props, "text_size")
    val fontWeight    = fontWeightProp(node.props)
    val fontStyle     = if (boolProp(node.props, "italic") == true) FontStyle.Italic else FontStyle.Normal
    val textAlign     = textAlignProp(node.props)
    val letterSpacing = floatProp(node.props, "letter_spacing")
    val lineHeightMul = floatProp(node.props, "line_height")
    val fontFamily    = fontFamilyProp(node.props)
    val tapHandle     = intProp(node.props, "on_tap")

    val resolvedLineHeight = if (lineHeightMul != null && fontSize != TextUnit.Unspecified)
        (lineHeightMul * fontSize.value).sp else TextUnit.Unspecified

    val tappableModifier = if (tapHandle != null)
        modifier.clickable { MobBridge.nativeSendTap(tapHandle) } else modifier

    // text_align is a no-op when the Text wraps to its content width — the
    // alignment only matters if the Text is wider than its content. Apply
    // fillMaxWidth in that case so center/right alignment behaves like iOS.
    val textModifier = if (textAlign != null && boolProp(node.props, "fill_width") != false &&
        floatProp(node.props, "width") == null) {
        tappableModifier.fillMaxWidth()
    } else tappableModifier

    // KATI-BEGIN(K-08 text-max-lines) mob_new=0.4.20
    // The design truncates with an ellipsis in 40+ places — every card title
    // carries `white-space:nowrap;overflow:hidden;text-overflow:ellipsis`.
    // Without this the prop was accepted and ignored, and long titles reflowed
    // the grid they were supposed to fit inside.
    val maxLines = (intProp(node.props, "max_lines") ?: Int.MAX_VALUE).coerceAtLeast(1)
    // KATI-END(K-08 text-max-lines)

    Text(
        text          = text,
        modifier      = textModifier,
        // KATI-BEGIN(K-10 no-font-padding) mob_new=0.4.20
        // Compose adds font padding above and below every line, so a text box
        // measures taller than the same text in the browser the design was
        // drawn in. It accumulates: Home's search bar sat 12dp low after two
        // lines of header. Off, so a line box is the line.
        style         = androidx.compose.ui.text.TextStyle(
            platformStyle = androidx.compose.ui.text.PlatformTextStyle(includeFontPadding = false)
        ),
        // KATI-END(K-10 no-font-padding)
        maxLines      = maxLines,
        overflow      = androidx.compose.ui.text.style.TextOverflow.Ellipsis,
        color         = color,
        fontSize      = fontSize,
        fontWeight    = fontWeight,
        fontStyle     = fontStyle,
        textAlign     = textAlign,
        lineHeight    = resolvedLineHeight,
        // KATI-BEGIN(K-10 letter-spacing-em) mob_new=0.4.20
        // `.em`, not `.sp`. The design states tracking in em — `.14em`, `-.03em`
        // — and applying those as sp made every one of 43 call sites roughly
        // 35x too tight, which reads as "the type is subtly wrong everywhere"
        // and never as a spacing bug.
        letterSpacing = letterSpacing?.em ?: TextUnit.Unspecified,
        // KATI-END(K-10 letter-spacing-em)
        fontFamily    = fontFamily,
    )
}

@Composable
private fun MobButton(node: MobNode, modifier: Modifier) {
    val label       = node.props["text"] as? String ?: ""
    val tapHandle   = intProp(node.props, "on_tap")
    val bgColor     = colorProp(node.props, "background")
    val cornerRad   = floatProp(node.props, "corner_radius") ?: 0f

    val fillWidth = boolProp(node.props, "fill_width") ?: false

    val colors = if (bgColor != Color.Unspecified)
        ButtonDefaults.buttonColors(containerColor = bgColor)
    else
        ButtonDefaults.buttonColors()

    // fill_width and corner_radius are driven by Elixir props (set in component
    // defaults but overridable per-node). Shape overrides M3's stadium default.
    Button(
        onClick  = { tapHandle?.let { MobBridge.nativeSendTap(it) } },
        modifier = if (fillWidth) modifier.fillMaxWidth() else modifier,
        colors   = colors,
        shape    = RoundedCornerShape(cornerRad.dp),
    ) {
        val textColor = colorProp(node.props, "text_color")
        val fontSize  = sizeProp(node.props, "text_size")
        Text(text = label, color = textColor, fontSize = fontSize,
             maxLines = 1, overflow = TextOverflow.Ellipsis)
    }
}

@Composable
private fun MobTextField(node: MobNode, modifier: Modifier) {
    val changeHandle  = intProp(node.props, "on_change")
    val focusHandle   = intProp(node.props, "on_focus")
    val blurHandle    = intProp(node.props, "on_blur")
    val submitHandle  = intProp(node.props, "on_submit")
    val placeholder   = node.props["placeholder"] as? String ?: ""
    val keyboardController = LocalSoftwareKeyboardController.current

    val isSecure = boolProp(node.props, "secure") ?: false
    // `secure: true` overrides any explicit `keyboard:` choice — Compose's
    // PasswordVisualTransformation pairs naturally with KeyboardType.Password
    // (autocorrect off, no suggestions strip). Apps wanting numeric PINs that
    // still mask the input should layer their own masking on a Number keyboard.
    val keyboardType = if (isSecure) {
        KeyboardType.Password
    } else when (node.props["keyboard"] as? String) {
        "number"  -> KeyboardType.Number
        "decimal" -> KeyboardType.Decimal
        "email"   -> KeyboardType.Email
        "phone"   -> KeyboardType.Phone
        "url"     -> KeyboardType.Uri
        else      -> KeyboardType.Text
    }
    val imeAction = when (node.props["return_key"] as? String) {
        "next"   -> ImeAction.Next
        "go"     -> ImeAction.Go
        "search" -> ImeAction.Search
        "send"   -> ImeAction.Send
        else     -> ImeAction.Done
    }

    var localValue by remember(node.props["value"]) {
        mutableStateOf(node.props["value"] as? String ?: "")
    }

    // Only fill width when explicitly asked. The unconditional fillMaxWidth
    // we used to apply broke layouts like ImperialInput's row of three
    // text_fields — the first field swallowed all the row's width and the
    // siblings got 0 px (silently invisible).
    val fillWidth = boolProp(node.props, "fill_width") ?: false
    val tfModifier = if (fillWidth) modifier.fillMaxWidth() else modifier

    TextField(
        value         = localValue,
        onValueChange = { new ->
            localValue = new
            changeHandle?.let { MobBridge.nativeSendChangeStr(it, new) }
        },
        placeholder   = { Text(placeholder) },
        modifier      = tfModifier
            .onFocusChanged { state ->
                if (state.isFocused) focusHandle?.let { MobBridge.nativeSendFocus(it) }
                else                 blurHandle?.let  { MobBridge.nativeSendBlur(it)  }
            },
        singleLine      = true,
        visualTransformation =
            if (isSecure) PasswordVisualTransformation() else VisualTransformation.None,
        keyboardOptions = KeyboardOptions(keyboardType = keyboardType, imeAction = imeAction),
        keyboardActions = KeyboardActions(onAny = {
            submitHandle?.let { MobBridge.nativeSendSubmit(it) }
            // dismiss for terminal actions; Next intentionally keeps keyboard open
            if (imeAction != ImeAction.Next) keyboardController?.hide()
        }),
    )
}

@Composable
private fun MobToggle(node: MobNode, modifier: Modifier) {
    val handle  = intProp(node.props, "on_change")
    val checked = boolProp(node.props, "value") ?: false
    val color   = colorProp(node.props, "color")
    Row(modifier = modifier, verticalAlignment = Alignment.CenterVertically) {
        node.props["label"]?.let {
            Text(text = it as String, modifier = Modifier.weight(1f))
        }
        Switch(
            checked         = checked,
            onCheckedChange = { new -> handle?.let { MobBridge.nativeSendChangeBool(it, new) } },
            colors          = if (color != Color.Unspecified)
                SwitchDefaults.colors(checkedThumbColor = color)
            else
                SwitchDefaults.colors(),
        )
    }
}

@Composable
private fun MobSlider(node: MobNode, modifier: Modifier) {
    val handle   = intProp(node.props, "on_change")
    val minVal   = floatProp(node.props, "min") ?: 0f
    val maxVal   = floatProp(node.props, "max") ?: 1f
    val color    = colorProp(node.props, "color")
    var localVal by remember(node.props["value"]) {
        mutableStateOf(floatProp(node.props, "value") ?: minVal)
    }
    Slider(
        value         = localVal,
        onValueChange = { new ->
            localVal = new
            handle?.let { MobBridge.nativeSendChangeFloat(it, new) }
        },
        valueRange    = minVal..maxVal,
        modifier      = modifier.fillMaxWidth(),
        colors        = if (color != Color.Unspecified)
            SliderDefaults.colors(thumbColor = color, activeTrackColor = color)
        else
            SliderDefaults.colors(),
    )
}

@Composable
private fun MobDivider(node: MobNode, modifier: Modifier) {
    val thickness = floatProp(node.props, "thickness") ?: 1f
    val color     = colorProp(node.props, "color")
    HorizontalDivider(
        modifier  = modifier,
        thickness = thickness.dp,
        color     = if (color != Color.Unspecified) color else DividerDefaults.color,
    )
}

@Composable
private fun MobSpacer(node: MobNode, modifier: Modifier) {
    val size = floatProp(node.props, "size")
    // size() sets both width and height so Spacer works as a gap in both Column and Row.
    Spacer(modifier = if (size != null) modifier.size(size.dp) else modifier)
}

@Composable
private fun MobProgress(node: MobNode, modifier: Modifier) {
    val value = floatProp(node.props, "value")
    val color = colorProp(node.props, "color")
    val trackColor = if (color != Color.Unspecified) color else Color.Unspecified

    if (value != null) {
        LinearProgressIndicator(
            progress    = { value },
            modifier    = modifier.fillMaxWidth(),
            color       = if (trackColor != Color.Unspecified) trackColor else Color.Unspecified,
        )
    } else {
        LinearProgressIndicator(
            modifier = modifier.fillMaxWidth(),
            color    = if (trackColor != Color.Unspecified) trackColor else Color.Unspecified,
        )
    }
}

@Composable
private fun MobImage(node: MobNode, modifier: Modifier) {
    val src          = node.props["src"] as? String
    val contentScale = when (node.props["content_mode"] as? String) {
        "fill"    -> ContentScale.Crop
        "stretch" -> ContentScale.FillBounds
        else      -> ContentScale.Fit
    }
    val cornerRadius = floatProp(node.props, "corner_radius") ?: 0f
    val fixedWidth   = floatProp(node.props, "width")
    val fixedHeight  = floatProp(node.props, "height")

    // Coil's AsyncImage expects a URL string for remote images or a File object for
    // local paths. Passing a bare path string as a model causes it to treat it as a
    // relative URL and fail silently. Detect local paths and wrap in File.
    val model: Any? = when {
        src == null -> null
        src.startsWith("http://") || src.startsWith("https://") -> src
        else -> java.io.File(src)
    }

    var m = modifier
    if (fixedWidth  != null) m = m.width(fixedWidth.dp)
    if (fixedHeight != null) m = m.height(fixedHeight.dp)
    if (cornerRadius > 0f)   m = m.clip(RoundedCornerShape(cornerRadius.dp))

    AsyncImage(
        model              = model,
        contentDescription = null,
        contentScale       = contentScale,
        modifier           = m,
    )
}

@Composable
private fun MobIcon(node: MobNode, modifier: Modifier) {
    val name        = node.props["name"] as? String ?: "questionmark"
    val tint        = colorProp(node.props, "text_color")
    val fontSizeSp  = sizeProp(node.props, "text_size")
    val sizeDp      = if (fontSizeSp != androidx.compose.ui.unit.TextUnit.Unspecified)
        fontSizeSp.value.dp else 24.dp
    val description = node.props["text"] as? String

    val onTap   = (node.props["on_tap"] as? Number)?.toInt()
    val baseMod = if (onTap != null) modifier.clickable { MobBridge.nativeSendTap(onTap) } else modifier

    Icon(
        imageVector       = materialIconFor(name),
        contentDescription = description,
        tint              = if (tint == Color.Unspecified) Color.Unspecified else tint,
        modifier          = baseMod.size(sizeDp),
    )
}

// Logical icon name → Material icon. Names mirror MobRootView.swift's
// sfSymbolName/1 so the same `name:` prop renders an Apple-styled icon on iOS
// and a Material-styled icon on Android. Unknown names fall back to a "?".
private fun materialIconFor(logical: String): androidx.compose.ui.graphics.vector.ImageVector =
    when (logical) {
        "settings"        -> Icons.Filled.Settings
        // KATI-BEGIN(K-12 auto-mirrored-icons) mob_new=0.4.20
        // Directional glyphs must mirror in RTL. Icons.AutoMirrored does it
        // from LocalLayoutDirection; Icons.Filled does not, so a back chevron
        // kept pointing the wrong way in fa. The design's group N calls this
        // out explicitly: the back chevron becomes arrow_forward in Persian.
        //
        // NOT mirrored, deliberately: play/skip transport controls, clock
        // faces, artwork and chart axes — the design lists these as locked.
        "back"            -> Icons.AutoMirrored.Filled.ArrowBack
        "forward"         -> Icons.AutoMirrored.Filled.ArrowForward
        // KATI-END(K-12 auto-mirrored-icons)
        "close"           -> Icons.Filled.Close
        "add"             -> Icons.Filled.Add
        "remove"          -> Icons.Filled.Remove
        "edit"            -> Icons.Filled.Edit
        "check"           -> Icons.Filled.Check
        // KATI-BEGIN(K-12 auto-mirrored-chevrons) mob_new=0.4.20
        "chevron_right"   -> Icons.AutoMirrored.Filled.KeyboardArrowRight
        "chevron_left"    -> Icons.AutoMirrored.Filled.KeyboardArrowLeft
        // Absolute variants for the cases that must NOT mirror.
        "chevron_absolute_right" -> Icons.Filled.ChevronRight
        "chevron_absolute_left"  -> Icons.Filled.ChevronLeft
        // KATI-END(K-12 auto-mirrored-chevrons)
        "chevron_up"      -> Icons.Filled.KeyboardArrowUp
        "chevron_down"    -> Icons.Filled.ExpandMore
        "info"            -> Icons.Filled.Info
        "warning"         -> Icons.Filled.Warning
        "error"           -> Icons.Filled.Error
        "search"          -> Icons.Filled.Search
        "trash"           -> Icons.Filled.Delete
        "share"           -> Icons.Filled.Share
        "more"            -> Icons.Filled.MoreVert
        "menu"            -> Icons.Filled.Menu
        "refresh"         -> Icons.Filled.Refresh
        "favorite"        -> Icons.Filled.FavoriteBorder
        "favorite_filled" -> Icons.Filled.Favorite
        "star"            -> Icons.Filled.StarBorder
        "star_filled"     -> Icons.Filled.Star
        "user"            -> Icons.Filled.Person
        "home"            -> Icons.Filled.Home
        "expand_more"     -> Icons.Filled.ExpandMore
        "expand_less"     -> Icons.Filled.ExpandLess
        // KATI-BEGIN(K-07 root-icons) mob_new=0.4.20
        // The stock map has 29 logical names and none for Kati's four roots,
        // so Calendar/Library/Stats would all fall through to QuestionMark.
        // This is a minimal slice of #34's work — enough for the shell to be
        // legible; the design's full Material Symbols coverage (673 icon spans,
        // plus the FILL axis for active tabs) is that ticket's job.
        "calendar"        -> Icons.Filled.CalendarMonth
        "library"         -> Icons.Filled.VideoLibrary
        "stats"           -> Icons.Filled.BarChart
        "plus"            -> Icons.Filled.Add
        // KATI-END(K-07 root-icons)
        else              -> Icons.Filled.QuestionMark
    }

private val MOB_JS_SHIM = """
(function(){
  if(window.mob)return;
  var _h=[];
  window.mob={
    send:function(d){MobNative.postMessage(JSON.stringify(d));},
    onMessage:function(h){_h.push(h);return function(){_h=_h.filter(function(x){return x!==h;});};},
    _dispatch:function(j){try{var d=JSON.parse(j);_h.forEach(function(h){h(d);});}catch(e){}}
  };
})();
""".trimIndent()

@Composable
private fun MobWebView(node: MobNode, modifier: Modifier) {
    val url       = node.props["url"] as? String ?: return
    val allowStr  = node.props["allow"] as? String ?: ""
    val allowList = allowStr.split(",").filter { it.isNotEmpty() }
    val title     = node.props["title"] as? String

    Column(modifier = modifier) {
        if (title != null) {
            Text(text = title, fontSize = 12.sp,
                 modifier = Modifier.padding(horizontal = 12.dp, vertical = 4.dp))
        }
        AndroidView(
            modifier = Modifier.weight(1f),
            factory  = { ctx ->
                android.webkit.WebView(ctx).apply {
                    settings.javaScriptEnabled = true
                    settings.domStorageEnabled = true
                    addJavascriptInterface(object : Any() {
                        @android.webkit.JavascriptInterface
                        fun postMessage(json: String) {
                            MobBridge.nativeDeliverWebViewMessage(0L, json)
                        }
                    }, "MobNative")
                    webViewClient = object : android.webkit.WebViewClient() {
                        override fun onPageFinished(view: android.webkit.WebView, pageUrl: String) {
                            view.evaluateJavascript(MOB_JS_SHIM, null)
                        }
                        override fun shouldOverrideUrlLoading(
                            view: android.webkit.WebView,
                            request: android.webkit.WebResourceRequest
                        ): Boolean {
                            if (allowList.isEmpty()) return false
                            val reqUrl = request.url.toString()
                            if (allowList.any { reqUrl.startsWith(it) }) return false
                            MobBridge.nativeDeliverWebViewBlocked(0L, reqUrl)
                            return true
                        }
                    }
                    MobBridge.webView = this
                    loadUrl(url)
                }
            },
            update = { wv -> MobBridge.webView = wv }
        )
    }
}

// ── Canvas (Mob.Canvas declarative draw spec) ───────────────────────────────
// Renders the node.props["draw"] list via Compose Canvas. Each op is a
// Map<String, Any?> with an "op" key plus op-specific fields, pre-resolved
// by the Elixir renderer (color tokens already converted to ARGB integers).
@Composable
private fun MobCanvas(node: MobNode, modifier: Modifier) {
    val width = floatProp(node.props, "width") ?: 0f
    val height = floatProp(node.props, "height") ?: 0f
    @Suppress("UNCHECKED_CAST")
    val ops: List<Map<String, Any?>> = when (val raw = node.props["draw"]) {
        is JSONArray -> (0 until raw.length()).map { i -> jsonObjectToMap(raw.getJSONObject(i)) }
        is List<*>   -> raw as List<Map<String, Any?>>
        else         -> emptyList()
    }

    val sized = if (width > 0f && height > 0f) {
        modifier.size(width.dp, height.dp)
    } else {
        modifier
    }

    Canvas(modifier = sized) {
        ops.forEach { op -> drawCanvasOp(op) }
    }
}

private fun DrawScope.drawCanvasOp(op: Map<String, Any?>) {
    val opName = op["op"] as? String ?: return
    val color = canvasColor(op["color"])
    val opacity = (op["opacity"] as? Double)?.toFloat() ?: 1f
    val isFill = (op["fill"] as? Boolean) ?: false
    val stroke = canvasStroke(op)

    when (opName) {
        "line" -> drawLine(
            color = color,
            start = Offset(canvasFloat(op["x1"]), canvasFloat(op["y1"])),
            end = Offset(canvasFloat(op["x2"]), canvasFloat(op["y2"])),
            strokeWidth = stroke.width,
            cap = stroke.cap,
            pathEffect = stroke.pathEffect,
            alpha = opacity
        )

        "circle" -> {
            val center = Offset(canvasFloat(op["x"]), canvasFloat(op["y"]))
            val radius = canvasFloat(op["r"])
            if (isFill) {
                drawCircle(color = color, radius = radius, center = center, alpha = opacity)
            } else {
                drawCircle(color = color, radius = radius, center = center, alpha = opacity, style = stroke)
            }
        }

        "ellipse" -> {
            val cx = canvasFloat(op["x"])
            val cy = canvasFloat(op["y"])
            val rx = canvasFloat(op["rx"])
            val ry = canvasFloat(op["ry"])
            val topLeft = Offset(cx - rx, cy - ry)
            val size = ComposeSize(rx * 2, ry * 2)
            if (isFill) {
                drawOval(color = color, topLeft = topLeft, size = size, alpha = opacity)
            } else {
                drawOval(color = color, topLeft = topLeft, size = size, alpha = opacity, style = stroke)
            }
        }

        "arc" -> {
            // Mob.Canvas arc: degrees, 0° to the right, sweeping clockwise.
            // Compose drawArc takes startAngle + sweepAngle in degrees, same convention.
            val cx = canvasFloat(op["x"])
            val cy = canvasFloat(op["y"])
            val r = canvasFloat(op["r"])
            val startDeg = canvasFloat(op["start_deg"])
            val endDeg = canvasFloat(op["end_deg"])
            val sweep = endDeg - startDeg
            drawArc(
                color = color,
                startAngle = startDeg,
                sweepAngle = sweep,
                useCenter = false,
                topLeft = Offset(cx - r, cy - r),
                size = ComposeSize(r * 2, r * 2),
                alpha = opacity,
                style = stroke
            )
        }

        "rect" -> {
            val topLeft = Offset(canvasFloat(op["x"]), canvasFloat(op["y"]))
            val size = ComposeSize(canvasFloat(op["w"]), canvasFloat(op["h"]))
            val radius = canvasFloat(op["radius"])
            if (radius > 0f) {
                val cornerRadius = androidx.compose.ui.geometry.CornerRadius(radius, radius)
                if (isFill) {
                    drawRoundRect(color = color, topLeft = topLeft, size = size,
                        cornerRadius = cornerRadius, alpha = opacity)
                } else {
                    drawRoundRect(color = color, topLeft = topLeft, size = size,
                        cornerRadius = cornerRadius, alpha = opacity, style = stroke)
                }
            } else {
                if (isFill) {
                    drawRect(color = color, topLeft = topLeft, size = size, alpha = opacity)
                } else {
                    drawRect(color = color, topLeft = topLeft, size = size, alpha = opacity, style = stroke)
                }
            }
        }

        "path" -> {
            @Suppress("UNCHECKED_CAST")
            val pts = op["points"] as? List<List<Any?>> ?: return
            if (pts.isEmpty()) return
            val closed = (op["closed"] as? Boolean) ?: false
            val path = Path().apply {
                moveTo(canvasFloat(pts[0].getOrNull(0)), canvasFloat(pts[0].getOrNull(1)))
                for (i in 1 until pts.size) {
                    lineTo(canvasFloat(pts[i].getOrNull(0)), canvasFloat(pts[i].getOrNull(1)))
                }
                if (closed || isFill) close()
            }
            if (isFill) {
                drawPath(path = path, color = color, alpha = opacity)
            } else {
                drawPath(path = path, color = color, alpha = opacity, style = stroke)
            }
        }

        "text" -> {
            val str = op["text"] as? String ?: return
            val size = canvasFloat(op["size"])
            val anchor = op["anchor"] as? String ?: "start"
            val weight = op["weight"] as? String
            // Compose has no DrawScope text primitive prior to TextMeasurer; the
            // simplest cross-version path is the platform Canvas via drawIntoCanvas.
            // Anchor is handled by measuring with Paint and offsetting x.
            drawIntoCanvas { canvas ->
                val paint = Paint().apply {
                    isAntiAlias = true
                    textSize = size
                    this.color = color.toArgb()
                    alpha = (opacity * 255).toInt().coerceIn(0, 255)
                    typeface = canvasTypeface(weight)
                }
                val measured = paint.measureText(str)
                val x = canvasFloat(op["x"])
                val y = canvasFloat(op["y"])
                val drawX = when (anchor) {
                    "center" -> x - measured / 2f
                    "end"    -> x - measured
                    else     -> x
                }
                // Compose Canvas positions text by baseline; offset by font ascent
                // so y is the top edge (matches SwiftUI Canvas convention).
                val baseline = y - paint.fontMetrics.ascent
                canvas.nativeCanvas.drawText(str, drawX, baseline, paint)
            }
        }

        "image" -> {
            // Image asset rendering deferred — needs context-aware loading from the
            // app's drawable resources or asset catalog. Tracked separately.
        }
    }
}

// Canvas coordinates from BEAM are in dp (matching the canvas's declared
// width/height). Compose's DrawScope works in pixels, so convert dp→px here.
private fun DrawScope.canvasFloat(v: Any?): Float {
    val dp = when (v) {
        is Float  -> v
        is Double -> v.toFloat()
        is Int    -> v.toFloat()
        is Long   -> v.toFloat()
        else      -> 0f
    }
    return dp.dp.toPx()
}

private fun canvasColor(v: Any?): Color = when (v) {
    is Long   -> Color(v.toInt())
    is Int    -> Color(v)
    is Double -> Color(v.toLong().toInt())
    is String -> {
        // Hex string fallback ("#rrggbb"). Pre-resolved ARGB integers are the
        // hot path; this is for raw color strings that bypass theme resolution.
        if (v.startsWith("#") && v.length == 7) {
            val rgb = v.substring(1).toLong(16)
            val r = ((rgb shr 16) and 0xFF).toInt()
            val g = ((rgb shr 8) and 0xFF).toInt()
            val b = (rgb and 0xFF).toInt()
            Color(red = r, green = g, blue = b)
        } else Color.Black
    }
    else      -> Color.Black
}

private fun DrawScope.canvasStroke(op: Map<String, Any?>): Stroke {
    val width = canvasFloat(op["width"]).let { if (it > 0f) it else 1f }
    val cap = when (op["cap"] as? String) {
        "round"  -> StrokeCap.Round
        "square" -> StrokeCap.Square
        else     -> StrokeCap.Butt
    }
    val join = when (op["join"] as? String) {
        "round" -> StrokeJoin.Round
        "bevel" -> StrokeJoin.Bevel
        else    -> StrokeJoin.Miter
    }
    @Suppress("UNCHECKED_CAST")
    val dashList = (op["dash"] as? List<Any?>)?.map { canvasFloat(it) }?.toFloatArray()
    val pathEffect = if (dashList != null && dashList.isNotEmpty()) {
        PathEffect.dashPathEffect(dashList, 0f)
    } else null
    return Stroke(width = width, cap = cap, join = join, pathEffect = pathEffect)
}

private fun canvasTypeface(weight: String?): Typeface = when (weight) {
    "bold", "semibold", "medium" -> Typeface.DEFAULT_BOLD
    else -> Typeface.DEFAULT
}

// ── GpuView ──────────────────────────────────────────────────────────────
//
// Fragment-shader-driven GPU surface backed by GLSurfaceView + GLES 3.0.
// Mirrors the iOS Mob.GpuView (MTKView + Metal) — same component API on
// the BEAM side; the shader source is GLSL ES 3.0 instead of MSL.
//
// The host owns the vertex shader (a passthrough that emits a full-screen
// quad with a varying v_uv in (0..1)). The user supplies a fragment
// shader that declares:
//
//   #version 300 es
//   precision highp float;
//   in vec2 v_uv;
//   out vec4 frag_color;
//   layout(std140) uniform Uniforms { ... };
//
// Uniforms arrive as a positional list packed by BEAM in the order the
// user wrote them. We std140-pack into a UBO at GL_BIND_BUFFER_BASE
// index 0, which the shader reads as a Uniforms block.

@Composable
private fun MobGpuView(node: MobNode, modifier: Modifier) {
    val width = floatProp(node.props, "width") ?: 0f
    val height = floatProp(node.props, "height") ?: 0f

    val shaderSrc: String = when (val raw = node.props["shader"]) {
        is String -> raw
        is JSONObject -> raw.optString("android", "")
        is Map<*, *> -> (raw["android"] as? String) ?: ""
        else -> ""
    }

    val uniformBytes: ByteArray = packGpuUniforms(node.props["uniforms"])

    val sized = if (width > 0f && height > 0f) {
        modifier.size(width.dp, height.dp)
    } else {
        modifier
    }

    // Surface the GL renderer's compile-error state to Compose so we can
    // overlay it on the failed view (parity with iOS MobGpuView). The
    // renderer runs on the GLSurfaceView's GL thread; the callback bounces
    // back to the main thread via mutableStateOf to keep Compose happy.
    val compileError = remember { mutableStateOf<String?>(null) }

    Box(modifier = sized) {
        AndroidView(
            factory = { ctx ->
                MobGpuSurfaceView(ctx) { err ->
                    ctx.mainExecutor.execute { compileError.value = err }
                }.also { v ->
                    v.applyShader(shaderSrc)
                    v.applyUniforms(uniformBytes)
                }
            },
            update = { view ->
                view.applyShader(shaderSrc)
                view.applyUniforms(uniformBytes)
            }
        )
        compileError.value?.let { err ->
            // Translucent red overlay matches the iOS MobGpuView contract:
            // a broken shader stays visible (not invisible) and the error
            // text is right on top of the offending view.
            Text(
                text = err,
                modifier = Modifier
                    .fillMaxSize()
                    .background(androidx.compose.ui.graphics.Color(0xC0FF0000))
                    .padding(8.dp),
                color = androidx.compose.ui.graphics.Color.White,
                fontSize = 12.sp
            )
        }
    }
}

private fun packGpuUniforms(raw: Any?): ByteArray {
    val list: List<Any?> = when (raw) {
        is JSONArray -> (0 until raw.length()).map { raw.get(it) }
        is List<*> -> raw
        else -> return ByteArray(0)
    }

    // std140-ish packing — matches the iOS-side Swift packer:
    //   number (Double/Long/Int) -> 4 bytes at 4-byte align
    //   JSONArray/List of 2      -> 8 bytes (float2) at 8-byte align
    //   JSONArray/List of 4      -> 16 bytes (float4) at 16-byte align
    //   float3 not supported in v1.
    //
    // The shader-side std140 Uniforms block reads members in the same
    // order. User is responsible for declaring matching positions.
    val sink = java.io.ByteArrayOutputStream()

    fun alignTo(n: Int) {
        val pad = (n - sink.size() % n) % n
        repeat(pad) { sink.write(0) }
    }

    fun writeF32(f: Float) {
        val bb = ByteBuffer.allocate(4).order(ByteOrder.nativeOrder())
        bb.putFloat(f)
        sink.write(bb.array())
    }

    fun writeI32(i: Int) {
        val bb = ByteBuffer.allocate(4).order(ByteOrder.nativeOrder())
        bb.putInt(i)
        sink.write(bb.array())
    }

    for (v in list) {
        when (v) {
            is Long -> {
                alignTo(4)
                writeI32(v.toInt())
            }
            is Int -> {
                alignTo(4)
                writeI32(v)
            }
            is Number -> {
                alignTo(4)
                writeF32(v.toFloat())
            }
            is JSONArray -> {
                val n = v.length()
                if (n == 2) {
                    alignTo(8)
                    writeF32(v.getDouble(0).toFloat())
                    writeF32(v.getDouble(1).toFloat())
                } else if (n == 4) {
                    alignTo(16)
                    for (i in 0 until 4) writeF32(v.getDouble(i).toFloat())
                }
            }
            is List<*> -> {
                val n = v.size
                if (n == 2) {
                    alignTo(8)
                    for (i in 0 until 2) writeF32((v[i] as Number).toFloat())
                } else if (n == 4) {
                    alignTo(16)
                    for (i in 0 until 4) writeF32((v[i] as Number).toFloat())
                }
            }
        }
    }
    return sink.toByteArray()
}

private class MobGpuSurfaceView(
    context: android.content.Context,
    onCompileError: (String?) -> Unit = {}
) : GLSurfaceView(context) {
    private val renderer = MobGpuRenderer(onCompileError)

    init {
        setEGLContextClientVersion(3)
        setRenderer(renderer)
        renderMode = RENDERMODE_CONTINUOUSLY
    }

    fun applyShader(source: String) {
        queueEvent { renderer.recompile(source) }
        requestRender()
    }

    fun applyUniforms(bytes: ByteArray) {
        queueEvent { renderer.uniformBytes = bytes }
        requestRender()
    }
}

private class MobGpuRenderer(private val onCompileError: (String?) -> Unit) :
    GLSurfaceView.Renderer {
    @Volatile
    var uniformBytes: ByteArray = ByteArray(0)

    private var program = 0
    private var ubo = 0
    private var vbo = 0
    private var vao = 0
    private var pendingSource: String? = null
    private var currentHash: Int = 0
    private var compileError: String? = null
    private var viewportW = 1
    private var viewportH = 1

    private fun setCompileError(err: String?) {
        if (err == compileError) return
        compileError = err
        onCompileError(err)
    }

    private val passthroughVertex = """
        #version 300 es
        in vec2 a_pos;
        out vec2 v_uv;
        void main() {
            gl_Position = vec4(a_pos, 0.0, 1.0);
            v_uv = a_pos * 0.5 + 0.5;
        }
    """.trimIndent()

    override fun onSurfaceCreated(gl: GL10?, config: EGLConfig?) {
        // Full-screen quad as a triangle strip in NDC.
        val verts = floatArrayOf(
            -1f, -1f,
             1f, -1f,
            -1f,  1f,
             1f,  1f
        )
        val bb = ByteBuffer.allocateDirect(verts.size * 4).order(ByteOrder.nativeOrder())
        val fb = bb.asFloatBuffer()
        fb.put(verts).position(0)

        val vbos = IntArray(1); GLES30.glGenBuffers(1, vbos, 0); vbo = vbos[0]
        GLES30.glBindBuffer(GLES30.GL_ARRAY_BUFFER, vbo)
        GLES30.glBufferData(GLES30.GL_ARRAY_BUFFER, verts.size * 4, fb, GLES30.GL_STATIC_DRAW)

        val vaos = IntArray(1); GLES30.glGenVertexArrays(1, vaos, 0); vao = vaos[0]
        GLES30.glBindVertexArray(vao)
        GLES30.glBindBuffer(GLES30.GL_ARRAY_BUFFER, vbo)
        GLES30.glEnableVertexAttribArray(0)
        GLES30.glVertexAttribPointer(0, 2, GLES30.GL_FLOAT, false, 0, 0)

        val ubos = IntArray(1); GLES30.glGenBuffers(1, ubos, 0); ubo = ubos[0]
    }

    override fun onSurfaceChanged(gl: GL10?, width: Int, height: Int) {
        viewportW = width; viewportH = height
        GLES30.glViewport(0, 0, width, height)
    }

    override fun onDrawFrame(gl: GL10?) {
        pendingSource?.let {
            compileNow(it)
            pendingSource = null
        }

        GLES30.glClearColor(0f, 0f, 0f, 1f)
        GLES30.glClear(GLES30.GL_COLOR_BUFFER_BIT)

        if (program == 0) return

        GLES30.glUseProgram(program)

        // Upload uniforms as UBO contents bound at binding point 0.
        if (uniformBytes.isNotEmpty()) {
            GLES30.glBindBuffer(GLES30.GL_UNIFORM_BUFFER, ubo)
            val bb = ByteBuffer.wrap(uniformBytes)
            GLES30.glBufferData(GLES30.GL_UNIFORM_BUFFER, uniformBytes.size, bb, GLES30.GL_DYNAMIC_DRAW)
            GLES30.glBindBufferBase(GLES30.GL_UNIFORM_BUFFER, 0, ubo)
        }

        GLES30.glBindVertexArray(vao)
        GLES30.glDrawArrays(GLES30.GL_TRIANGLE_STRIP, 0, 4)
    }

    fun recompile(source: String) {
        val hash = source.hashCode()
        if (hash == currentHash && program != 0) return
        currentHash = hash
        pendingSource = source
    }

    private fun compileNow(source: String) {
        val vs = compileShader(GLES30.GL_VERTEX_SHADER, passthroughVertex) ?: return
        val fs = compileShader(GLES30.GL_FRAGMENT_SHADER, source) ?: run {
            GLES30.glDeleteShader(vs)
            return
        }

        val prog = GLES30.glCreateProgram()
        GLES30.glAttachShader(prog, vs)
        GLES30.glAttachShader(prog, fs)
        GLES30.glBindAttribLocation(prog, 0, "a_pos")
        GLES30.glLinkProgram(prog)
        val status = IntArray(1)
        GLES30.glGetProgramiv(prog, GLES30.GL_LINK_STATUS, status, 0)
        if (status[0] == 0) {
            setCompileError("link: " + GLES30.glGetProgramInfoLog(prog))
            GLES30.glDeleteProgram(prog)
            GLES30.glDeleteShader(vs); GLES30.glDeleteShader(fs)
            program = 0
            return
        }

        // Bind the shader's `Uniforms` block to binding point 0.
        val blockIdx = GLES30.glGetUniformBlockIndex(prog, "Uniforms")
        if (blockIdx != GLES30.GL_INVALID_INDEX) {
            GLES30.glUniformBlockBinding(prog, blockIdx, 0)
        }

        if (program != 0) GLES30.glDeleteProgram(program)
        program = prog
        setCompileError(null)
        GLES30.glDeleteShader(vs); GLES30.glDeleteShader(fs)
    }

    private fun compileShader(type: Int, source: String): Int? {
        val s = GLES30.glCreateShader(type)
        GLES30.glShaderSource(s, source)
        GLES30.glCompileShader(s)
        val status = IntArray(1)
        GLES30.glGetShaderiv(s, GLES30.GL_COMPILE_STATUS, status, 0)
        if (status[0] == 0) {
            setCompileError(GLES30.glGetShaderInfoLog(s))
            GLES30.glDeleteShader(s)
            return null
        }
        return s
    }
}

@Composable
private fun MobVideoPlayer(node: MobNode, modifier: Modifier) {
    val src = node.props["src"] as? String ?: return
    val autoplay = boolProp(node.props, "autoplay") ?: false
    val context = LocalContext.current
    // ExoPlayer / Media3 video player.
    // Requires: implementation 'androidx.media3:media3-exoplayer:1.3.0'
    //           implementation 'androidx.media3:media3-ui:1.3.0'
    // Stubbed until Media3 dependency is added to build.gradle.
    // Replace this Box with the full player implementation when the dep is present:
    androidx.compose.foundation.layout.Box(
        modifier = modifier
            .background(Color.Black),
        contentAlignment = androidx.compose.ui.Alignment.Center
    ) {
        Text("Video: $src", color = Color.White, fontSize = 12.sp)
    }
}

@Composable
private fun MobLazyList(node: MobNode, modifier: Modifier) {
    val handle    = intProp(node.props, "on_end_reached")
    // Use a persistent LazyListState keyed by handle so scroll position survives
    // BEAM re-renders. rememberLazyListState() would reset to 0 on every data
    // update because AnimatedContent creates a fresh composition for each new
    // RootState, even when only list items changed (no navigation).
    val listState = remember(handle) {
        if (handle != null) MobBridge.getOrCreateLazyListState(handle)
        else LazyListState()
    }

    val reachedEnd by remember {
        derivedStateOf {
            val lastVisible = listState.layoutInfo.visibleItemsInfo.lastOrNull()?.index ?: -1
            val total       = listState.layoutInfo.totalItemsCount
            total > 0 && lastVisible >= total - 1
        }
    }

    LaunchedEffect(reachedEnd) {
        if (reachedEnd) handle?.let { MobBridge.nativeSendTap(it) }
    }

    LazyColumn(state = listState, modifier = modifier.fillMaxWidth()) {
        items(node.children) { child -> RenderNode(child) }
    }
}

@Composable
private fun MobTabBar(node: MobNode, modifier: Modifier) {
    val tabs     = tabDefsProp(node.props)
    val activeId = (node.props["active"] as? String) ?: tabs.firstOrNull()?.get("id") ?: ""
    val handle   = intProp(node.props, "on_tab_select")
    val activeIdx = tabs.indexOfFirst { it["id"] == activeId }.coerceAtLeast(0)

    Scaffold(
        modifier  = modifier,
        bottomBar = {
            NavigationBar {
                tabs.forEachIndexed { index, tab ->
                    NavigationBarItem(
                        selected = index == activeIdx,
                        onClick  = { handle?.let { MobBridge.nativeSendChangeStr(it, tab["id"] ?: "") } },
                        label    = { Text(tab["label"] ?: "") },
                        icon     = { Icon(materialIconForLogical(tab["icon"] ?: ""), contentDescription = tab["label"]) }
                    )
                }
            }
        }
    ) { innerPadding ->
        if (activeIdx < node.children.size) {
            RenderNode(node.children[activeIdx], Modifier.padding(innerPadding))
        }
    }
}

// ── Modifier helpers ──────────────────────────────────────────────────────────

private fun nodeModifier(props: Map<String, Any?>): Modifier {
    var m: Modifier = Modifier
    val cornerRadius = floatProp(props, "corner_radius") ?: 0f
    val shape = if (cornerRadius > 0f) RoundedCornerShape(cornerRadius.dp) else null

    // KATI-BEGIN(K-08 box-shadow) mob_new=0.4.20
    // CSS box-shadow, including SPREAD.
    //
    // The design's dominant card recipe is
    //   0 1px 2px rgba(26,25,23,.04), 0 12px 24px -18px rgba(26,25,23,.6)
    // and it is used 262 times. The defining part is the -18px spread on the
    // second layer: it pulls the large soft shadow in so the card looks lifted
    // off warm paper rather than outlined. Compose's `Modifier.shadow` takes a
    // single elevation and has NO spread at all, so it cannot draw this — which
    // is why #33 chose drawBehind + Paint.setShadowLayer instead.
    //
    // Prop format mirrors CSS, layers separated by `|`:
    //   shadow="0 1 2 0 #0A1A1917 | 0 12 24 -18 #991A1917"
    //           dx dy blur spread #AARRGGBB
    shadowLayers(props)?.let { layers ->
        m = m.drawBehind {
            drawIntoCanvas { canvas ->
                val r = cornerRadius.dp.toPx()
                layers.forEach { l ->
                    val paint = android.graphics.Paint().apply {
                        isAntiAlias = true
                        // The shape itself is transparent; only the shadow it
                        // casts is drawn, which is what lets layers stack
                        // without each one painting over the last.
                        color = android.graphics.Color.TRANSPARENT
                        setShadowLayer(
                            maxOf(l.blur.dp.toPx(), 0.01f),
                            l.dx.dp.toPx(),
                            l.dy.dp.toPx(),
                            l.color
                        )
                    }
                    val sp = l.spread.dp.toPx()
                    canvas.nativeCanvas.drawRoundRect(
                        -sp, -sp, size.width + sp, size.height + sp, r, r, paint
                    )
                }
            }
        }
    }
    // KATI-END(K-08 box-shadow)

    // Background must come before padding so it fills the full area (including
    // padding space). If background were applied after padding, it would only
    // draw behind the inner content area — making empty boxes invisible.
    // When a corner radius is present, clip the background to that shape so
    // rectangular bleed doesn't show through the rounded corners.
    longColorProp(props, "background")?.let { bg ->
        m = if (shape != null) m.background(bg, shape) else m.background(bg)
    }

    // KATI-BEGIN(K-11 gradient) mob_new=0.4.20
    // After the background, so a node can carry both: the artwork heroes paint
    // a fallback colour and then the fade over it.
    if (props["gradient"] is String) {
        m = m.drawBehind {
            gradientBrush(props, size.height)?.let { brush -> drawRect(brush = brush) }
        }
    }
    // KATI-END(K-11 gradient)

    // Border (opt-in: requires both border_color and border_width). Drawn on
    // the same shape as the background so rounded boxes get a proper outline.
    val borderColor = longColorProp(props, "border_color")
    val borderWidth = floatProp(props, "border_width") ?: 0f
    if (borderColor != null && borderWidth > 0f) {
        m = if (shape != null) m.border(borderWidth.dp, borderColor, shape)
            else m.border(borderWidth.dp, borderColor)
    }

    // KATI-BEGIN(K-06 clip-before-padding) mob_new=0.4.20
    // Clip BEFORE padding. Compose applies modifiers outside-in, so
    // `.padding().clip()` clips to the already-shrunk CONTENT box rather than
    // the node: the rounded mask's left edge lands exactly on the text, and any
    // glyph with negative left side bearing gets shaved. Measured: in a
    // corner_radius card the leading "N" of "Nothing" and "w" of "whole" were
    // visibly cut, while an otherwise identical card without corner_radius
    // rendered them perfectly.
    //
    // The stock comment claimed the opposite of what the order does ("so the
    // rounded mask covers the entire padded area, not just the inner content").
    // Background is already drawn with `shape`, so moving the clip earlier
    // keeps corners rounded and stops the mask biting into content.
    //
    // High impact for Kati: the design uses the rounded-card recipe 262 times.
    if (shape != null) m = m.clip(shape)
    // KATI-END(K-06 clip-before-padding)

    val uniform = intProp(props, "padding")
    val top     = intProp(props, "padding_top")
    val right   = intProp(props, "padding_right")
    val bottom  = intProp(props, "padding_bottom")
    val left    = intProp(props, "padding_left")
    val hasEdge = top != null || right != null || bottom != null || left != null
    // KATI-BEGIN(K-08 non-negative-padding) mob_new=0.4.20
    // Clamp at zero. Compose throws IllegalArgumentException("Padding must be
    // non-negative") from inside the render pass, which takes down the whole
    // activity — the app vanishes to the launcher with no Elixir error. A
    // negative padding is a mistake in one node's markup; it should not be
    // fatal to the process. (CSS negative margin is not padding anyway: it
    // also shrinks the layout box. Use offset_x/offset_y for overlap.)
    fun pad(v: Int?): Int = (v ?: uniform ?: 0).coerceAtLeast(0)
    // KATI-END(K-08 non-negative-padding)
    m = when {
        hasEdge  -> m.padding(
            top    = pad(top).dp,
            end    = pad(right).dp,
            bottom = pad(bottom).dp,
            start  = pad(left).dp,
        )
        uniform != null -> m.padding(uniform.dp.coerceAtLeast(0.dp))
        else            -> m
    }

    if (boolProp(props, "fill_width") == true) m = m.fillMaxWidth()
    // fill_height: true stretches the node to the parent's vertical bounds.
    // Used by full-screen overlay boxes whose center alignment needs the
    // viewport as its reference frame, not the contained children's height.
    if (boolProp(props, "fill_height") == true) m = m.fillMaxHeight()

    // Explicit width / height — when set, the node uses that exact size
    // instead of stretching to fill its parent. Used by SquareTriangle's
    // ring cells (110x110 boxes acting as rings via corner_radius +
    // border).
    floatProp(props, "width")?.let  { w -> m = m.width(w.dp) }
    floatProp(props, "height")?.let { h -> m = m.height(h.dp) }

    // KATI-BEGIN(K-28 min-size) mob_new=0.4.20
    // min_width / min_height — the drawing's number as a FLOOR, not a cap.
    //
    // `width` is the wrong tool for anything measured to fit TEXT, because the
    // text is the part that grows. At Android's 235% Dynamic Type the
    // schedule's `<Column width={44}>` time gutter still measured 44dp while
    // "08:00" needed roughly 78, so it rendered "0…" — losing the one label
    // that says which hour a card belongs to (#79). Nothing was logged; a
    // fixed width is not an error, it is just too small.
    //
    // The rule this makes expressible, which #79 asks to settle as policy
    // rather than per-screen: a fixed `width`/`height` is for content that does
    // NOT scale with text — an icon disc, a poster, a dot, a rule, a swatch.
    // Anything sized to fit text takes `min_width`/`min_height`, which pins the
    // drawing's measurement at 100% and lets it grow past that.
    //
    // widthIn(min=) composes with an earlier fillMaxWidth rather than fighting
    // it, so a node can still be told both to fill and to never go under.
    floatProp(props, "min_width")?.let  { w -> m = m.widthIn(min = w.dp) }
    floatProp(props, "min_height")?.let { h -> m = m.heightIn(min = h.dp) }
    // KATI-END(K-28 min-size)

    // aspect_ratio: lock a node to width:height = ratio. Common use is
    // <Box fill_width={true} aspect_ratio={1.0}> to make a square area
    // (e.g. camera preview + overlay canvas that need to match the
    // model's center-cropped square frame so coords align).
    floatProp(props, "aspect_ratio")?.let { r -> if (r > 0f) m = m.aspectRatio(r) }

    // KATI-BEGIN(K-16 rotate-and-clip) mob_new=0.4.20
    // Two marks the design makes WITHOUT their own Material Symbol, and which
    // therefore can never enter the icon subset — the generator derives that
    // set by scanning the drawings for symbol names, and these are not there.
    //
    // `rotate` — screen 02's air-date group draws its collapse chevron by
    // rotating expand_more 180deg in CSS. With no rotation the group had no
    // glyph to close itself with and shipped permanently open-or-shut. Costs
    // one Compose modifier; the alternative was re-subsetting the font for a
    // glyph that is another glyph upside down.
    //
    // `clip_width` — screen 33's half star is a gradient across ONE star
    // glyph, hard-stopped at 50%. Compose cannot crop text: every Text is
    // built with TextOverflow.Ellipsis, so a narrower Box ellipsises the glyph
    // away rather than cutting it, and corner_radius clips painting only.
    // Clipping the DRAW instead reproduces exactly what the CSS does — an
    // empty star with a filled one clipped over it — so 4.5 stars reads as
    // four and a half rather than as five.
    //
    // Both take the node as drawn and change only how it is painted, so
    // neither affects measurement or the layout around it.
    floatProp(props, "rotate")?.let { deg -> if (deg != 0f) m = m.rotate(deg) }

    floatProp(props, "clip_width")?.let { f ->
        if (f < 1f) {
            val fraction = f.coerceAtLeast(0f)
            m = m.drawWithContent {
                clipRect(right = size.width * fraction) { this@drawWithContent.drawContent() }
            }
        }
    }
    // KATI-END(K-16 rotate-and-clip)

    // Per-node offset is NOT applied here. Compose's Modifier.offset on the
    // node's own modifier chain didn't displace siblings reliably when stacking
    // multiple offset boxes inside a parent Box. RenderNode wraps the whole
    // node in an outer Box(Modifier.offset(...)) instead — see RenderNode.
    return m
}

// ── Typography helpers ────────────────────────────────────────────────────────

private fun fontWeightProp(props: Map<String, Any?>): FontWeight? =
    when (props["font_weight"] as? String) {
        "bold"     -> FontWeight.Bold
        // KATI-BEGIN(K-10 extrabold) mob_new=0.4.20
        // kati_sans_800 ships and the design uses 800 for every hero figure,
        // but the map had no arm for it — so `font_weight="extrabold"` fell to
        // null and those titles rendered at 400.
        "extrabold" -> FontWeight.ExtraBold
        // KATI-END(K-10 extrabold)
        "semibold" -> FontWeight.SemiBold
        "medium"   -> FontWeight.Medium
        "light"    -> FontWeight.Light
        "thin"     -> FontWeight.Thin
        else       -> null
    }

private fun textAlignProp(props: Map<String, Any?>): TextAlign? =
    when (props["text_align"] as? String) {
        "center" -> TextAlign.Center
        "right"  -> TextAlign.End
        // KATI-BEGIN(K-12 absolute-text-align) mob_new=0.4.20
        // Direction-relative values, and ABSOLUTE ones for the things the
        // design says must not mirror: artwork captions, clock faces,
        // play/skip controls, chart axes. Without absolute values there is no
        // way to say "left even in RTL".
        "start"          -> TextAlign.Start
        "end"            -> TextAlign.End
        "absolute_left"  -> TextAlign.Left
        "absolute_right" -> TextAlign.Right
        "justify"        -> TextAlign.Justify
        // KATI-END(K-12 absolute-text-align)
        else     -> null
    }

// Recursively convert org.json.JSONObject/JSONArray trees to plain Kotlin
// Map<String, Any?> / List<Any?> so they're usable by code that expects
// Kotlin collections (e.g. MobCanvas's "draw" op list).
private fun jsonObjectToMap(obj: JSONObject): Map<String, Any?> {
    val result = mutableMapOf<String, Any?>()
    for (key in obj.keys()) {
        result[key] = jsonValueToKotlin(obj.get(key))
    }
    return result
}

private fun jsonValueToKotlin(v: Any?): Any? = when (v) {
    is JSONObject -> jsonObjectToMap(v)
    is JSONArray  -> (0 until v.length()).map { i -> jsonValueToKotlin(v.get(i)) }
    JSONObject.NULL -> null
    else -> v
}

// KATI-BEGIN(K-11 gradient-parser) mob_new=0.4.20
// CSS-shaped linear gradients: `gradient="to_top #FFEFECE7 4% #00EFECE7"`.
//
// The design uses these to make text readable over artwork — a 190pt band
// lifting paper back over the bottom of a photograph — and for the fade under
// the dock. Painting a flat opaque rectangle instead, which is what Kati did,
// does not fade: it guillotines whatever it covers.
//
// Direction first (`to_top` or `to_bottom`), then colour/stop pairs. A stop is
// optional and defaults to an even distribution.
private fun gradientBrush(props: Map<String, Any?>, height: Float): Brush? {
    val raw = props["gradient"] as? String ?: return null
    val parts = raw.trim().split(Regex("\\s+"))
    if (parts.size < 3) return null

    val toTop = parts[0] == "to_top"
    val stops = mutableListOf<Pair<Float, Int>>()
    var i = 1
    var index = 0
    val colourCount = parts.drop(1).count { it.startsWith("#") }

    while (i < parts.size) {
        val token = parts[i]
        if (!token.startsWith("#")) { i++; continue }
        val colour = try { android.graphics.Color.parseColor(token) } catch (_: Exception) { i++; continue }
        val next = parts.getOrNull(i + 1)
        val stop = if (next != null && next.endsWith("%")) {
            i += 2
            (next.dropLast(1).toFloatOrNull() ?: 0f) / 100f
        } else {
            i += 1
            if (colourCount <= 1) 0f else index.toFloat() / (colourCount - 1)
        }
        stops += stop to colour
        index++
    }

    if (stops.size < 2) return null

    // `to_top` means the FIRST colour sits at the bottom edge, so the stops are
    // mirrored — Compose's verticalGradient runs top to bottom.
    val ordered = if (toTop) stops.map { (s, c) -> (1f - s) to c }.sortedBy { it.first } else stops
    val colorStops = ordered.map { (s, c) -> s to Color(c) }.toTypedArray()

    return Brush.verticalGradient(colorStops = colorStops, startY = 0f, endY = height)
}
// KATI-END(K-11 gradient-parser)

// KATI-BEGIN(K-08 box-shadow-parser) mob_new=0.4.20
private data class KatiShadow(
    val dx: Float, val dy: Float, val blur: Float, val spread: Float, val color: Int
)

// "0 12 24 -18 #991A1917 | 0 1 2 0 #0A1A1917" -> layers, painter's order.
// A malformed layer is dropped rather than throwing: a wrong shadow is a
// cosmetic defect, a crash in the render loop is a dead screen.
private fun shadowLayers(props: Map<String, Any?>): List<KatiShadow>? {
    val raw = props["shadow"] as? String ?: return null

    val layers = raw.split("|").mapNotNull { part ->
        val f = part.trim().split(Regex("\\s+"))
        if (f.size != 5) return@mapNotNull null
        try {
            KatiShadow(
                f[0].toFloat(), f[1].toFloat(), f[2].toFloat(), f[3].toFloat(),
                android.graphics.Color.parseColor(f[4])
            )
        } catch (_: Exception) { null }
    }

    return layers.ifEmpty { null }
}
// KATI-END(K-08 box-shadow-parser)

// KATI-BEGIN(K-14 bundled-fonts) mob_new=0.4.20
// The design is drawn in Plus Jakarta Sans, DM Mono, Vazirmatn and Material
// Symbols Rounded. A stock Mob app renders every one of them as Roboto,
// because the original of this function asked Typeface.create for a FAMILY
// NAME the device has never heard of and silently fell back — and because
// nothing passed a `font` prop at all, so it returned null before even
// trying. Kati's whole visual identity is those four faces, so they ship.
//
// All static instances, deliberately. Compose can drive a variable font's
// axes through FontVariation, but that is an API bet paid for in build-deploy
// cycles; instancing wght 400..800 with fontTools costs nothing at runtime and
// cannot behave differently on one device. The icon font is instanced twice,
// FILL 0 and FILL 1, which is the only axis value the design ever uses (33
// occurrences, all `'FILL' 1`) and covers the active tab.
//
// Sizes: the icon font is a 143-glyph subset of a 15 MB original, 47 KB per
// instance. `mix kati.gen.icons` regenerates the name->codepoint map from the
// design and prints the pyftsubset command when the set changes.
private val katiSans by lazy {
    FontFamily(
        Font(R.font.kati_sans_400, FontWeight.Normal),
        Font(R.font.kati_sans_500, FontWeight.Medium),
        Font(R.font.kati_sans_600, FontWeight.SemiBold),
        Font(R.font.kati_sans_700, FontWeight.Bold),
        Font(R.font.kati_sans_800, FontWeight.ExtraBold),
    )
}

private val katiFa by lazy {
    FontFamily(
        Font(R.font.kati_fa_400, FontWeight.Normal),
        Font(R.font.kati_fa_500, FontWeight.Medium),
        Font(R.font.kati_fa_600, FontWeight.SemiBold),
        Font(R.font.kati_fa_700, FontWeight.Bold),
        Font(R.font.kati_fa_800, FontWeight.ExtraBold),
    )
}

private val katiMono by lazy { FontFamily(Font(R.font.kati_mono)) }
private val katiSymbols by lazy { FontFamily(Font(R.font.kati_symbols)) }
private val katiSymbolsFilled by lazy { FontFamily(Font(R.font.kati_symbols_filled)) }

private fun fontFamilyProp(props: Map<String, Any?>): FontFamily? =
    // Both spellings. The template reads `font`; ~MOB markup naturally says
    // `font_family`, and a prop that is silently ignored is the single most
    // expensive kind of mistake in this codebase — it renders, it just renders
    // wrong, and nothing anywhere says so.
    when (val name = (props["font_family"] ?: props["font"]) as? String) {
        // No prop means body text, and body text is Plus Jakarta Sans. This is
        // the case that matters: it is every unstyled Text in the app.
        null, "sans" -> katiSans
        "mono", "monospace" -> katiMono
        "fa" -> katiFa
        "symbols" -> katiSymbols
        "symbols_filled" -> katiSymbolsFilled
        else -> try { FontFamily(Typeface.create(name, Typeface.NORMAL)) }
                catch (_: Exception) { katiSans }
    }
// KATI-END(K-14 bundled-fonts)

// ── Tab bar helpers ───────────────────────────────────────────────────────────

// Logical icon name → Material Icon. Mirrors the iOS sfSymbolName/2 lookup so
// the same Elixir tab declaration ("history", "qr_code", etc.) renders a
// platform-native icon on each side. Falls back to a visible Star for unknown
// names so missing mappings show up in the UI rather than failing silently.
private fun materialIconForLogical(logical: String): androidx.compose.ui.graphics.vector.ImageVector =
    when (logical) {
        "home"      -> Icons.Filled.Home
        "history"   -> Icons.Filled.History
        "list"      -> Icons.Filled.List
        "qr_code"   -> Icons.Filled.QrCode
        "link"      -> Icons.Filled.Link
        "snowflake" -> Icons.Filled.AcUnit
        "star"      -> Icons.Filled.Star
        "settings"  -> Icons.Filled.Settings
        "search"    -> Icons.Filled.Search
        "user"      -> Icons.Filled.Person
        else        -> Icons.Filled.Star
    }

private fun tabDefsProp(props: Map<String, Any?>): List<Map<String, String>> {
    return when (val raw = props["tabs"]) {
        is JSONArray -> (0 until raw.length()).map { i ->
            val obj = raw.getJSONObject(i)
            mapOf("id" to obj.optString("id"), "label" to obj.optString("label"), "icon" to obj.optString("icon"))
        }
        else -> emptyList()
    }
}

// ── Prop extraction ───────────────────────────────────────────────────────────

// Vertical alignment for Row from the `align:` prop — :top / :center / :bottom
// (atom from Elixir arrives as a String). Defaults to CenterVertically because
// that matches the most common visual expectation (e.g. icon next to title);
// opt back into Top with align: :top.
private fun rowAlignProp(props: Map<String, Any?>): Alignment.Vertical =
    when (props["align"] as? String) {
        "top"    -> Alignment.Top
        "bottom" -> Alignment.Bottom
        else     -> Alignment.CenterVertically
    }

// 2D alignment for Box content — same string keys as iOS so the
// renderer doesn't have to discriminate per platform.
private fun boxAlignProp(props: Map<String, Any?>): Alignment =
    when (props["align"] as? String) {
        "center"          -> Alignment.Center
        "top"             -> Alignment.TopCenter
        "top_center"      -> Alignment.TopCenter
        "top_trailing"    -> Alignment.TopEnd
        "leading"         -> Alignment.CenterStart
        "trailing"        -> Alignment.CenterEnd
        "bottom"          -> Alignment.BottomCenter
        "bottom_leading"  -> Alignment.BottomStart
        "bottom_center"   -> Alignment.BottomCenter
        "bottom_trailing" -> Alignment.BottomEnd
        else              -> Alignment.TopStart
    }

private fun colorProp(props: Map<String, Any?>, key: String): Color =
    longColorProp(props, key) ?: Color.Unspecified

private fun longColorProp(props: Map<String, Any?>, key: String): Color? =
    when (val v = props[key]) {
        is Long   -> Color(v.toInt())
        is Int    -> Color(v)
        is Double -> Color(v.toLong().toInt())
        else      -> null
    }

private fun sizeProp(props: Map<String, Any?>, key: String): TextUnit =
    when (val v = props[key]) {
        is Double -> v.toFloat().sp
        is Float  -> v.sp
        is Int    -> v.sp
        is Long   -> v.toFloat().sp
        else      -> TextUnit.Unspecified
    }

private fun intProp(props: Map<String, Any?>, key: String): Int? =
    when (val v = props[key]) {
        is Int    -> v
        is Long   -> v.toInt()
        is Double -> v.toInt()
        else      -> null
    }

private fun floatProp(props: Map<String, Any?>, key: String): Float? =
    when (val v = props[key]) {
        is Double -> v.toFloat()
        is Float  -> v
        is Int    -> v.toFloat()
        is Long   -> v.toFloat()
        else      -> null
    }

private fun boolProp(props: Map<String, Any?>, key: String): Boolean? =
    when (val v = props[key]) {
        is Boolean -> v
        is String  -> v == "true"
        else       -> null
    }

// ── Notification broadcast receiver ─────────────────────────────────────────
// Receives alarms from AlarmManager and posts the notification to the system tray.
// Also delivers the event to the running BEAM screen process if one is registered.
class NotificationReceiver : BroadcastReceiver() {
    override fun onReceive(context: android.content.Context, intent: android.content.Intent) {
        val title   = intent.getStringExtra("title") ?: ""
        val body    = intent.getStringExtra("body")  ?: ""
        val id      = intent.getStringExtra("id")    ?: "mob"
        val dataStr = intent.getStringExtra("data")  ?: "{}"

        val nm = context.getSystemService(android.content.Context.NOTIFICATION_SERVICE) as NotificationManager
        val notif = NotificationCompat.Builder(context, MobBridge.NOTIF_CHANNEL_ID)
            .setSmallIcon(android.R.drawable.ic_dialog_info)
            .setContentTitle(title)
            .setContentText(body)
            .setAutoCancel(true)
            .build()
        nm.notify(id.hashCode(), notif)

        // KATI-BEGIN(K-01 notify-forget) mob_new=0.4.20
        // A one-shot alarm that has fired must not be restored at next boot.
        KatiNotificationStore.forget(context, id)
        // KATI-END(K-01 notify-forget)

        // Deliver to BEAM if a screen is running
        val json = """{"id":"$id","title":"$title","body":"$body","source":"local","data":$dataStr}"""
        // We can't deliver directly here since we don't have a pid.
        // The notification delegate in iOS style is set up differently on Android.
        // Delivery happens via MobBridge when the notification is tapped (MainActivity intent).
        // For foreground delivery, the screen registers via Mob.Permissions before scheduling.
    }

}
